const $=id=>document.getElementById(id), canvas=$('arena'),ctx=canvas.getContext('2d');
let W=800,H=500,mode='laser',angle=32,speed=1,running=!matchMedia('(prefers-reduced-motion: reduce)').matches,bounces=0,origin={x:.27,y:.38},p={x:0,y:0},v={x:0,y:0},history=[],drag=null,last=0;
const color='#d3fa6b';
function bounds(){return mode==='dvd'?{x:31,y:18}:{x:5,y:5}}
function direction(){const a=angle*Math.PI/180;v={x:Math.cos(a),y:Math.sin(a)}}
function sync(){ $('angle').value=angle;$('angleValue').textContent=angle+'°';$('angleReadout').textContent=angle+'°';$('bounces').textContent=String(bounces).padStart(3,'0');$('pause').textContent=running?'Ⅱ Pause':'▶ Play';$('status').textContent=running?'IN MOTION':'PAUSED';$('statusDot').style.opacity=running?1:.35;}
function restart(){const b=bounds();p={x:b.x+origin.x*(W-2*b.x),y:b.y+origin.y*(H-2*b.y)};direction();history=[{...p}];bounces=0;sync()}
function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;const d=devicePixelRatio||1;canvas.width=W*d;canvas.height=H*d;ctx.setTransform(d,0,0,d,0,0);restart()}
function hit(point,dir){const b=bounds();let tx=dir.x>1e-9?(W-b.x-point.x)/dir.x:dir.x< -1e-9?(b.x-point.x)/dir.x:Infinity;let ty=dir.y>1e-9?(H-b.y-point.y)/dir.y:dir.y< -1e-9?(b.y-point.y)/dir.y:Infinity;const t=Math.max(0,Math.min(tx,ty));return {t,x:point.x+dir.x*t,y:point.y+dir.y*t,flipX:Math.abs(tx-t)<1e-7,flipY:Math.abs(ty-t)<1e-7}}
function move(dist){let n=0;while(dist>1e-7&&n++<100){const h=hit(p,v);if(h.t>dist){p.x+=v.x*dist;p.y+=v.y*dist;break}p={x:h.x,y:h.y};history.push({...p});if(history.length>80)history.shift();dist-=h.t;if(h.flipX)v.x=-v.x;if(h.flipY)v.y=-v.y;bounces++;$('bounces').textContent=String(bounces).padStart(3,'0')}}
function draw(){ctx.clearRect(0,0,W,H);ctx.fillStyle='#283020';for(let x=20;x<W;x+=24)for(let y=20;y<H;y+=24){ctx.beginPath();ctx.arc(x,y,.65,0,Math.PI*2);ctx.fill()}
if($('trajectory').checked){let q={...p},d={...v};ctx.save();ctx.setLineDash([4,7]);ctx.lineWidth=1;ctx.strokeStyle='#d3fa6b30';ctx.beginPath();ctx.moveTo(q.x,q.y);for(let i=0;i<+$('reflections').value;i++){const h=hit(q,d);ctx.lineTo(h.x,h.y);q={x:h.x,y:h.y};if(h.flipX)d.x=-d.x;if(h.flipY)d.y=-d.y}ctx.stroke();ctx.restore()}
if($('trail').checked&&history.length){ctx.save();ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.shadowColor=color;ctx.shadowBlur=9;ctx.globalAlpha=.75;ctx.beginPath();ctx.moveTo(history[0].x,history[0].y);history.slice(1).forEach(q=>ctx.lineTo(q.x,q.y));ctx.lineTo(p.x,p.y);ctx.stroke();ctx.restore()}
const b=bounds(),o={x:b.x+origin.x*(W-2*b.x),y:b.y+origin.y*(H-2*b.y)};ctx.strokeStyle='#d3fa6b70';ctx.lineWidth=1;ctx.beginPath();ctx.arc(o.x,o.y,8,0,Math.PI*2);ctx.moveTo(o.x-12,o.y);ctx.lineTo(o.x+12,o.y);ctx.moveTo(o.x,o.y-12);ctx.lineTo(o.x,o.y+12);ctx.stroke();
ctx.save();ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=20;if(mode==='laser'){ctx.beginPath();ctx.arc(p.x,p.y,4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(p.x,p.y,1.8,0,Math.PI*2);ctx.fill()}else{ctx.font='italic 900 23px Arial';ctx.textAlign='center';ctx.fillText('DVD',p.x,p.y+3);ctx.beginPath();ctx.ellipse(p.x,p.y+11,24,3,0,0,Math.PI*2);ctx.fill()}ctx.restore();if(drag){ctx.strokeStyle='#fff';ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(drag.x,drag.y);ctx.lineTo(drag.endX,drag.endY);ctx.stroke();ctx.setLineDash([])}}
function tick(t){const dt=last?Math.min((t-last)/1000,.05):0;last=t;if(running&&!drag)move(dt*160*speed);draw();requestAnimationFrame(tick)}
$('angle').oninput=e=>{angle=+e.target.value;restart()};$('speed').oninput=e=>{speed=+e.target.value;$('speedValue').textContent=speed.toFixed(1)+'×'};$('reflections').oninput=e=>$('reflectionsValue').textContent=e.target.value;
for(const id of ['posX','posY'])$(id).onchange=()=>{let x=+$('posX').value,y=+$('posY').value;if(!Number.isFinite(x)||!Number.isFinite(y))return;origin={x:Math.min(99,Math.max(1,x))/100,y:Math.min(99,Math.max(1,y))/100};$('posX').value=Math.round(origin.x*100);$('posY').value=Math.round(origin.y*100);restart()};
for(const m of ['laser','dvd'])$(m).onclick=()=>{mode=m;for(const id of ['laser','dvd']){$(id).classList.toggle('selected',id===m);$(id).setAttribute('aria-pressed',String(id===m))}$('modeLabel').textContent=m==='dvd'?'DVD ICON':'LASER';restart()};
$('pause').onclick=()=>{running=!running;sync()};$('restart').onclick=restart;document.addEventListener('keydown',e=>{if(/INPUT|BUTTON|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();$('pause').click()}if(e.key.toLowerCase()==='r')restart()});
function pointer(e){const r=canvas.getBoundingClientRect(),b=bounds();return{x:Math.max(b.x+1,Math.min(W-b.x-1,e.clientX-r.left)),y:Math.max(b.y+1,Math.min(H-b.y-1,e.clientY-r.top))}}
canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);const q=pointer(e),b=bounds();origin={x:(q.x-b.x)/(W-2*b.x),y:(q.y-b.y)/(H-2*b.y)};drag={...q,endX:q.x,endY:q.y};$('posX').value=Math.round(origin.x*100);$('posY').value=Math.round(origin.y*100);restart()};canvas.onpointermove=e=>{if(!drag)return;const q=pointer(e);drag.endX=q.x;drag.endY=q.y;if(Math.hypot(q.x-drag.x,q.y-drag.y)>5){angle=(Math.round(Math.atan2(q.y-drag.y,q.x-drag.x)*180/Math.PI)+360)%360;restart()}};canvas.onpointerup=()=>{drag=null};canvas.onpointercancel=()=>{drag=null};
new ResizeObserver(resize).observe(canvas);sync();requestAnimationFrame(tick);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_reflection',description:'Set the launch angle and traveler, then restart the mirror-room simulation.',inputSchema:{type:'object',properties:{angle:{type:'number',minimum:0,maximum:359},traveler:{type:'string',enum:['laser','dvd']}},required:['angle','traveler'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isFinite(input.angle)||input.angle<0||input.angle>359||!['laser','dvd'].includes(input.traveler))throw Error('Provide an angle from 0 to 359 and traveler laser or dvd.');angle=Math.round(input.angle);$(input.traveler).click();return{angle,traveler:mode,running}}})).catch(()=>{})}catch{}}
